import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse(`{"title":"Monetization","description":"","frontmatter":{"epic":6,"title":"Monetization","status":"⏳ In Progress — 6.1 done; 6.2, 6.3 blocked on real Apple/Google/payment-provider accounts this environment doesn't have","scope":"shared","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/shared/monetization.md"},"headers":[],"relativePath":"sovereign-edge/epics/shared/monetization.md","filePath":"sovereign-edge/epics/shared/monetization.md"}`),s={name:"sovereign-edge/epics/shared/monetization.md"};function i(r,e,c,d,l,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-monetization" tabindex="-1">Epic: Monetization <a class="header-anchor" href="#epic-monetization" aria-label="Permalink to &quot;Epic: Monetization&quot;">​</a></h1><blockquote><p>Paid connectors — platform in-app purchase on mobile, direct sale on desktop. The core app and baseline connectors are free forever and are never gated by anything in this epic.</p></blockquote><p><strong>Scope note:</strong> spans both apps by design (mobile IAP, desktop direct sale), not scoped to one — see the taxonomy note in <a href="./../README.html#layout">docs/epics/README.md</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Mirrors <code>sovereign</code>&#39;s own entitlement-based plugin monetization (RFC 0003 in that repo) at the concept level — a connector author declares pricing, an entitlement unlocks it — but the purchase rail diverges by platform because mobile app stores require their own in-app purchase system for unlocking digital features inside a binary, which <code>sovereign</code>&#39;s self-hosted web platform never had to deal with.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-6-1-—-entitlement-model" tabindex="-1">✅ 6.1 — Entitlement model <a class="header-anchor" href="#✅-6-1-—-entitlement-model" aria-label="Permalink to &quot;✅ 6.1 — Entitlement model&quot;">​</a></h4><p><strong>Goal:</strong> A platform-agnostic notion of &quot;this connector is unlocked for this user,&quot; independent of which purchase rail granted it.</p><p><strong>Deliverables:</strong></p><ul><li>An entitlement record/token concept a paid connector checks before it&#39;s usable, decoupled from the purchase mechanism itself (mirrors <code>sovereign</code>&#39;s signed-entitlement pattern, adapted for a mobile/desktop client instead of a server).</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1, <code>pricing</code> field).</p><p><strong>Review checklist:</strong></p><ul><li>A connector marked paid is unusable without a valid entitlement, on any platform.</li></ul><p><strong>Decided:</strong></p><ul><li><strong>A plain local record, not a signed token</strong>, asked of the user explicitly since research 0001 points at <code>sovereign</code>&#39;s own signed-entitlement model (RFC 0003 in that repo, not available in this repo) as the concept to mirror. There is no real issuer to sign against yet — tasks 6.2 (mobile IAP) and 6.3 (desktop direct sale), the only things that would ever produce a real purchase receipt, are both blocked on real Apple/Google/ payment-provider accounts this environment doesn&#39;t have. Building real signature verification now would mean the app both signing and verifying its own token, which proves nothing a plain record doesn&#39;t. <code>{connectorId, grantedAt, source}</code> — <code>source</code> is an opaque string a real caller will pass (<code>&quot;ios-iap&quot;</code>/<code>&quot;android-iap&quot;</code>/<code>&quot;desktop-direct&quot;</code> once 6.2/6.3 land); nothing here inspects it, so a real signed receipt can be recorded later without changing this shape or any call site.</li><li><strong>Same plain-JSON persisted-file pattern as <code>grants.ts</code>/<code>grants.rs</code></strong>: mobile&#39;s <code>connectors/permissions/entitlements.ts</code> (<code>entitlements.json</code> under <code>Paths.document/connectors/</code>) and desktop&#39;s <code>connectors/permissions/entitlements.rs</code> (<code>entitlements.json</code> under <code>state.connectors_dir</code>, taking the directory as an explicit parameter the same way <code>installed.rs</code> does). Lives beside <code>grants</code>/<code>grants.rs</code> rather than beside <code>store</code>/<code>installed.rs</code>: grants and entitlements both answer &quot;may this connector run&quot; (consent, then payment); <code>installed</code> answers &quot;which manifests does this device have.&quot;</li><li><strong>The gate applies at two points, both platforms</strong>: the install screen/ command (defense in depth — the store screen already disables the install button for a paid entry, but <code>ConnectorInstallScreen.tsx</code>&#39;s <code>install()</code> and <code>install_connector</code>&#39;s Tauri command both re-check <code>isConnectorUsable</code>/<code>is_connector_usable</code> rather than trusting the UI gate), and <code>executeConnectorCall</code>/<code>execute_connector_call</code> themselves, once at the shared entry point rather than duplicated per tier — a new <code>&#39;not-entitled&#39;</code>/<code>FailureReason::NotEntitled</code> failure reason, mirroring exactly how <code>&#39;not-permitted&#39;</code>/<code>FailureReason::NotPermitted</code> is already handled by <code>connectorOrchestration.ts</code>/<code>orchestration.rs</code>&#39;s user-facing message mapping.</li></ul><p><strong>Honest gap:</strong></p><ul><li><strong>Nothing in this app can grant a real entitlement yet.</strong> <code>grantEntitlement</code>/ <code>grant_entitlement</code> exist and are fully wired into every gate, but no UI calls them — that&#39;s exactly what 6.2 (mobile IAP) and 6.3 (desktop direct sale) will do once they exist. Until then, a paid connector in the store is permanently locked with no path to unlock it from inside the app; this is the correct, honest state (no real purchase rail should silently pretend to have one), not a bug to work around.</li></ul><p><strong>Verified:</strong></p><ul><li>Mobile: <code>pnpm --filter mobile typecheck</code>/<code>lint</code>/<code>test</code> (268 tests, up from 258 — <code>entitlements.test.ts</code> plus a new <code>execute.test.ts</code> case). Desktop: <code>cargo fmt</code>/<code>clippy</code>/<code>test</code> (137 tests, up from 128) and <code>pnpm --filter desktop typecheck</code>/<code>lint</code>/<code>test</code> (49 tests, unchanged) all clean. <code>pnpm check:offline</code> unaffected on both apps.</li><li><strong>Real end-to-end proof, not just <code>entitlements.rs</code>&#39;s own unit tests in isolation</strong>: a new <code>execute.rs</code> integration test (<code>refuses_an_unentitled_paid_connector_even_when_granted</code>) grants a real on-disk <em>grant</em> for a paid manifest, confirms <code>execute_connector_call</code> still refuses it with <code>NotEntitled</code>, then calls the real <code>grant_entitlement</code> (the same function a future IAP success handler would call) against real on-disk state and confirms the gate passes (fails downstream on the network call instead, since the fixture&#39;s origin isn&#39;t a real server — proving the <em>gate</em>, not the whole request, changed), then <code>revoke_entitlement</code> and confirms it locks again. Mobile&#39;s <code>execute.test.ts</code> proves the same gate placement via its existing mock-based convention (<code>isConnectorUsable</code> mocked the same way <code>isAllowed</code> already is in that file).</li><li>Real desktop debug binary build (<code>pnpm tauri build --debug --no-bundle</code>) and launch-smoke check: process starts, stays running, no panic.</li></ul><hr><h4 id="📋-6-2-—-mobile-in-app-purchase-integration" tabindex="-1">📋 6.2 — Mobile in-app purchase integration <a class="header-anchor" href="#📋-6-2-—-mobile-in-app-purchase-integration" aria-label="Permalink to &quot;📋 6.2 — Mobile in-app purchase integration&quot;">​</a></h4><p><strong>Goal:</strong> Unlock paid connectors via Apple/Google&#39;s required IAP systems.</p><p><strong>Deliverables:</strong></p><ul><li>StoreKit (iOS) and Google Play Billing (Android) integration.</li><li>Purchase → entitlement-grant flow feeding into the Task 6.1 model.</li></ul><p><strong>Dependencies:</strong> Task 6.1.</p><p><strong>Review checklist:</strong></p><ul><li>A real sandbox purchase on both platforms results in the corresponding connector becoming usable, and a refund/revocation removes access.</li></ul><hr><h4 id="📋-6-3-—-desktop-direct-sale-flow" tabindex="-1">📋 6.3 — Desktop direct-sale flow <a class="header-anchor" href="#📋-6-3-—-desktop-direct-sale-flow" aria-label="Permalink to &quot;📋 6.3 — Desktop direct-sale flow&quot;">​</a></h4><p><strong>Goal:</strong> Sell paid connectors directly on desktop, where there&#39;s no app- store payment requirement.</p><p><strong>Deliverables:</strong></p><ul><li>A direct purchase flow (payment provider TBD) granting the same entitlement model as Task 6.1, without an IAP intermediary.</li></ul><p><strong>Dependencies:</strong> Task 6.1, Desktop App epic.</p><p><strong>Review checklist:</strong></p><ul><li>A desktop purchase and a mobile purchase of the same connector both result in the identical entitlement check passing.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-store-sdk.html">Connector Store &amp; SDK</a></li></ul>',37)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
